namespace ProductsApi.Models;

public enum Category
{
    Electronics,
    Clothing,
    Food,
    Books
}

public class Product
{
    public int Id { get; set; }
    public required string Name { get; set; }
    public decimal Price { get; set; }
    public Category Category { get; set; }
    public DateTime CreatedAt { get; set; }
}

public class CreateProductRequest
{
    public required string Name { get; set; }
    public decimal Price { get; set; }
    public Category Category { get; set; }
}

using ProductsApi.Models;

namespace ProductsApi.Services;

public interface IProductService
{
    IReadOnlyList<Product> GetAll();
    Product? GetById(int id);
    Product Create(CreateProductRequest request);
}

using ProductsApi.Models;

namespace ProductsApi.Services;

public class InMemoryProductService : IProductService
{
    private readonly List<Product> _products = [];
    private int _nextId = 1;

    public IReadOnlyList<Product> GetAll() => _products.AsReadOnly();

    public Product? GetById(int id) => _products.FirstOrDefault(p => p.Id == id);

    public Product Create(CreateProductRequest request)
    {
        var product = new Product
        {
            Id = _nextId++,
            Name = request.Name,
            Price = request.Price,
            Category = request.Category,
            CreatedAt = DateTime.UtcNow
        };

        _products.Add(product);
        return product;
    }
}

using Microsoft.AspNetCore.Http.HttpResults;
using ProductsApi.Models;
using ProductsApi.Services;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<IProductService, InMemoryProductService>();
builder.Services.AddEndpointsApiExplorer();
builder.Services.AddSwaggerGen(options =>
{
    options.SwaggerDoc("v1", new Microsoft.OpenApi.Models.OpenApiInfo
    {
        Title = "Products API",
        Version = "v1",
        Description = "An API for managing products across various categories."
    });
});

var app = builder.Build();

app.UseSwagger();
app.UseSwaggerUI();

var products = app.MapGroup("/api/products")
    .WithTags("Products");

products.MapGet("/", (IProductService service) => service.GetAll())
    .WithName("GetAllProducts")
    .WithSummary("List all products")
    .WithDescription("Retrieves the complete list of products in the catalog.")
    .Produces<IReadOnlyList<Product>>(StatusCodes.Status200OK);

products.MapGet("/{id:int}", Results<Ok<Product>, NotFound> (int id, IProductService service) =>
{
    var product = service.GetById(id);
    return product is not null
        ? TypedResults.Ok(product)
        : TypedResults.NotFound();
})
    .WithName("GetProductById")
    .WithSummary("Get a product by ID")
    .WithDescription("Retrieves a single product by its unique identifier. Returns 404 if not found.")
    .Produces<Product>(StatusCodes.Status200OK)
    .Produces(StatusCodes.Status404NotFound);

products.MapPost("/", Created<Product> (CreateProductRequest request, IProductService service) =>
{
    var product = service.Create(request);
    return TypedResults.Created($"/api/products/{product.Id}", product);
})
    .WithName("CreateProduct")
    .WithSummary("Create a new product")
    .WithDescription("Creates a new product in the catalog. The product ID and creation timestamp are assigned automatically.")
    .Produces<Product>(StatusCodes.Status201Created);

app.Run();

